const AdvancedOptionsPlayerSetup: Component = () => {
	const playerOptions = PlayerSetupParametersModel.get().players;
	const slots = PlayerSetupParametersModel.get().configuration;
	const hasOpenSlots = createMemo(() => slots.openSlots().length > 0);

	function closeSlot(slotToRemove: ConfigurationPlayerSlot) {
		const activeSlots = slots.activeSlots();
		if (activeSlots.length <= 2) return;

		// Find the actual position of the clicked slot.
		const removedIndex = activeSlots.findIndex((currentSlot) => currentSlot.playerId === slotToRemove.playerId);
		if (removedIndex === -1) return;

		// Save every configuration before modifying the slots.
		const configurations = activeSlots.map((currentSlot) => ({
			leader: getLeader(currentSlot).value.value,
			civilization: getCiv(currentSlot).value.value,
		}));

		// Shift every following configuration one position upward.
		for (let index = removedIndex; index < activeSlots.length - 1; index++) {
			const currentSlot = activeSlots[index];
			const nextConfiguration = configurations[index + 1];

			if (!currentSlot || !nextConfiguration) continue;

			getLeader(currentSlot).setValue(nextConfiguration.leader);
			getCiv(currentSlot).setValue(nextConfiguration.civilization);
		}

		// Reset and close the last slot after shifting its data.
		const lastSlot = activeSlots[activeSlots.length - 1];
		if (!lastSlot) return;

		getLeader(lastSlot).setValue("RANDOM");
		getCiv(lastSlot).setValue("RANDOM");
		lastSlot.setSlotStatus(SlotStatus.SS_CLOSED);
		slots.reload();
	}

	function openSlot() {
		if (hasOpenSlots()) {
			const availableSlots = slots.openSlots();
			const slot = availableSlots[availableSlots.length - 1];
			if (!slot) return;
			slots.openSlots()[0].setSlotStatus(SlotStatus.SS_COMPUTER);
			slots.reload();
		}
	}

	function getCiv(slot: ConfigurationPlayerSlot) {
		return playerOptions[slot.playerId]?.PlayerCivilization;
	}

	function getLeader(slot: ConfigurationPlayerSlot) {
		return playerOptions[slot.playerId]?.PlayerLeader;
	}

	function sortPossibleValues(possibleValues: GameSetupDomainValue[] | undefined) {
		if (!possibleValues) return;
		return [...possibleValues].sort((a, b) => {
			if (a.sortIndex != b.sortIndex) return a.sortIndex - b.sortIndex;

			const nameA = Locale.compose(GameSetup.resolveString(a.name) as string);
			const nameB = Locale.compose(GameSetup.resolveString(b.name) as string);
			return Locale.compare(nameA, nameB);
		});
	}

	return (
		<ScrollArea class="flex-auto">
			<SpatialSlot
				name="advanced-player-options-slot"
				class="flex flex-col flex-auto w-full pr-8"
			>
				<div class="flex flex-row mt-4">
					<div class="w-12" />
					<div class="flex flex-row flex-auto">
						<div
							class="m-2 flex-1 items-center justify-center uppercase font-title tracking-150 pointer-events-auto"
							role="columnheader"
						>
							<L10n.Compose text="LOC_GENERIC_LEADER" />
						</div>
						<div
							class="m-2 flex-1 items-center justify-center uppercase font-title tracking-150 pointer-events-auto"
							role="columnheader"
						>
							<L10n.Compose text="LOC_GENERIC_CIVILIZATION" />
						</div>
					</div>
					<div class="w-14" />
				</div>

				<For each={slots.activeSlots()}>
					{(slot, slotNum) => (
						<div class="flex flex-row">
							<div class="w-12 flex items-center justify-start text-base font-title">{slotNum() + 1}</div>
							<div class="flex flex-row flex-auto px-6">
								<Dropdown
									class="my-2 mr-2 w-1\/2"
									defaultValue={getLeader(slot).value}
									selectedItemTemplate={(leader) => (
										<Tooltip initialHPosition={TooltipHorizontalPosition.RIGHT}>
											<Tooltip.Trigger>
												<AdvancedOptionPlayerOption param={leader} />
											</Tooltip.Trigger>
											<Tooltip.Content>
												<LeaderTooltip data={leader} />
											</Tooltip.Content>
										</Tooltip>
									)}
									onItemSelected={(value: GameSetupDomainValue) =>
										getLeader(slot).setValue(value.value)
									}
								>
									<For each={sortPossibleValues(getLeader(slot).domain.possibleValues)}>
										{(leader) => (
											<Tooltip initialHPosition={TooltipHorizontalPosition.RIGHT}>
												<Tooltip.Trigger>
													<DropdownItem value={leader}>
														<AdvancedOptionPlayerOption param={leader} />
													</DropdownItem>
												</Tooltip.Trigger>
												<Tooltip.Content>
													<LeaderTooltip data={leader} />
												</Tooltip.Content>
											</Tooltip>
										)}
									</For>
								</Dropdown>
								<Dropdown
									class="my-2 ml-2 w-1\/2"
									defaultValue={getCiv(slot).value}
									selectedItemTemplate={(civ) => (
										<Tooltip initialHPosition={TooltipHorizontalPosition.LEFT}>
											<Tooltip.Trigger>
												<AdvancedOptionPlayerOption param={civ} />
											</Tooltip.Trigger>
											<Tooltip.Content>
												<CivTooltip data={civ} />
											</Tooltip.Content>
										</Tooltip>
									)}
									onItemSelected={(value: GameSetupDomainValue) => getCiv(slot).setValue(value.value)}
								>
									<For each={sortPossibleValues(getCiv(slot).domain.possibleValues)}>
										{(civ) => (
											<Tooltip initialHPosition={TooltipHorizontalPosition.LEFT}>
												<Tooltip.Trigger>
													<DropdownItem value={civ}>
														<AdvancedOptionPlayerOption param={civ} />
													</DropdownItem>
												</Tooltip.Trigger>
												<Tooltip.Content>
													<CivTooltip data={civ} />
												</Tooltip.Content>
											</Tooltip>
										)}
									</For>
								</Dropdown>
							</div>
							<div class="w-14">
								<Show when={!slot.isLocalPlayer}>
									<Activatable
										class={`m-2 size-12 cursor-pointer group relative`}
										onActivate={() => closeSlot(slot)}
									>
										<div class="close-button__bg absolute inset-0" />
										<div class="close-button__bg-hover absolute inset-0 opacity-0 group-hover\:opacity-100 group-focus\:opacity-100 transition-opacity" />
										<div class="close-button__bg-pressed absolute inset-0 opacity-0 group-active\:opacity-100 group-pressed\:opacity-100" />
									</Activatable>
								</Show>
							</div>
						</div>
					)}
				</For>
				<Button
					class="mt-4 my-10"
					onActivate={openSlot}
					disabled={!hasOpenSlots()}
				>
					<div class="flex-auto flex flex-row justify-start items-center">
						<div
							class="advanced-options_add-player-plus bg-no-repeat bg-contain size-12 m-3"
							classList={{ "opacity-50": !hasOpenSlots() }}
						/>
						<L10n.Compose text="LOC_ADVANCED_OPTIONS_ADD_PLAYER" />
					</div>
				</Button>
			</SpatialSlot>
		</ScrollArea>
	);
};

