interface AdvancedOptionFieldProps {
	showHeader?: boolean;
	parameter: ReactiveGameSetupParameter;
}

const strInvertSelection = GameSetup.makeString("InvertSelection");

const AdvancedOptionMultiselectField: Component<AdvancedOptionFieldProps> = (props) => {
	const stringCache = useGameSetupStringCacheContext();
	const isInverted = createMemo(() => props.parameter.uxHint == strInvertSelection);

	const valueItems = (domainValue: GameSetupDomainValue) => [
		{
			name: "LOC_UI_ENABLED",
			value: !isInverted(),
			description: `{${stringCache.resolve(domainValue.description)}}[N] [N]{LOC_UI_ENABLED}`,
		},
		{
			name: "LOC_UI_DISABLED",
			value: isInverted(),
			description: `{${stringCache.resolve(domainValue.description)}}[N] [N]{LOC_UI_DISABLED}`,
		},
	];

	function hasValue(value: GameSetupParameterValue) {
		return !!props.parameter.values.find((v) => v.value == value);
	}

	function setValue(value: GameSetupDomainValue, isIncluded: boolean) {
		const newValues = [...props.parameter.values.map((v) => v.value as number)];
		const valueIndex = newValues.findIndex((v) => v == value.value);

		if (isIncluded) {
			if (valueIndex == -1) {
				newValues.push(value.value as number);
			}
		} else {
			if (valueIndex >= 0) {
				newValues.splice(valueIndex, 1);
			}
		}

		props.parameter.setValue(newValues);
	}

	function getRowClass(index: number) {
		return index % 2 == 0 ? "bg-primary-4" : "bg-primary-5";
	}

	return (
		<Show
			when={props.showHeader}
			fallback={
				<Index each={props.parameter.domain.possibleValues ?? []}>
					{(domainValue, index) => (
						<div class={getRowClass(index)}>
							<AdvancedOptionsParameterRow rowName={stringCache.resolve(domainValue().name)}>
								<SelectorSmall
									class="m-1"
									items={valueItems(domainValue())}
									setSelectedValue={(value) => setValue(domainValue(), value)}
									selectedValue={() => hasValue(domainValue().value)}
									previousActionKey="nav-left"
									nextActionKey="nav-right"
								/>
							</AdvancedOptionsParameterRow>
						</div>
					)}
				</Index>
			}
		>
			<AdvancedOptionsAccordian title={stringCache.resolve(props.parameter.name)}>
				<Index each={props.parameter.domain.possibleValues ?? []}>
					{(domainValue, index) => (
						<div class={getRowClass(index)}>
							<AdvancedOptionsParameterRow rowName={stringCache.resolve(domainValue().name)}>
								<SelectorSmall
									class="m-1"
									items={valueItems(domainValue())}
									setSelectedValue={(value) => setValue(domainValue(), value)}
									selectedValue={() => hasValue(domainValue().value)}
									previousActionKey="nav-left"
									nextActionKey="nav-right"
								/>
							</AdvancedOptionsParameterRow>
						</div>
					)}
				</Index>
			</AdvancedOptionsAccordian>
		</Show>
	);
};

