const AdvancedOptionSelectorField: Component<AdvancedOptionFieldProps> = (props) => {
	const stringCache = useGameSetupStringCacheContext();
	function extractSelectorValues(values: GameSetupDomainValue[]) {
		return values.map((v) => {
			const description = stringCache.resolve(v.description);
			return {
				name: stringCache.resolve(v.name),
				value: v.value,
				description: `{${stringCache.resolve(props.parameter.description)}}${description ? `[N] [N]{${description}}` : ""}`,
			};
		});
	}
	function isParameterValid(param: ReactiveGameSetupParameter) {
		return (
			typeof param == "object" &&
			!param.hidden &&
			!param.destroyed &&
			(param.domain.type != GameSetupDomainType.Select || (param.domain.possibleValues?.length ?? 0) > 1) &&
			param.invalidReason == GameSetupParameterInvalidReason.Valid
		);
	}

	return (
		<SelectorSmall
			class="m-1"
			items={extractSelectorValues(props.parameter.domain.possibleValues ?? [])}
			setSelectedValue={(value) => props.parameter.setValue(value)}
			selectedValue={() => props.parameter.value.value}
			disabled={!isParameterValid(props.parameter)}
			previousActionKey="nav-left"
			nextActionKey="nav-right"
		/>
	);
};

const AdvancedOptionTextField: Component<AdvancedOptionFieldProps> = (props) => {
	const value = createMemo(() => (props.parameter.value.value ?? "").toString());
	const maxNumericValue = Math.pow(2, 31);

	function setValue<T extends string>(value: T) {
		if (
			props.parameter.domain.type == GameSetupDomainType.Integer ||
			props.parameter.domain.type == GameSetupDomainType.UnsignedInteger
		) {
			// Numeric
			const numericValue = Number.parseInt(value);
			if (numericValue) {
				const clampedNumericValue = Math.min(Math.max(numericValue, -1 * maxNumericValue), maxNumericValue - 1);
				props.parameter.setValue(clampedNumericValue);
				return clampedNumericValue.toString();
			}
		} else {
			// Text
			props.parameter.setValue(value);
		}

		return value;
	}

	return (
		<AudioContextProvider segment="Option">
			<TextInput
				class="w-72 m-1"
				setValue={setValue}
				value={value}
				enableVirtualKeyboard={true}
				tabIndex={-1}
			/>
		</AudioContextProvider>
	);
};

const AdvancedReadonlyTextField: Component<AdvancedOptionFieldProps> = (props) => {
	const value = createMemo(() => (props.parameter.value.value ?? "").toString());
	return <>{value()}</>;
};

const AdvancedOptionField: Component<AdvancedOptionFieldProps> = (props) => {
	const stringCache = useGameSetupStringCacheContext();

	return (
		<Switch>
			<Match when={props.parameter.readOnly}>
				<AdvancedOptionsParameterRow rowName={stringCache.resolve(props.parameter.name)}>
					<AdvancedReadonlyTextField parameter={props.parameter} />
				</AdvancedOptionsParameterRow>
			</Match>
			<Match when={props.parameter.domain.type == GameSetupDomainType.Select && props.parameter.array}>
				<AdvancedOptionMultiselectField
					parameter={props.parameter}
					showHeader={props.showHeader}
				/>
			</Match>
			<Match when={props.parameter.domain.type == GameSetupDomainType.Select}>
				<AdvancedOptionsParameterRow rowName={stringCache.resolve(props.parameter.name)}>
					<AdvancedOptionSelectorField parameter={props.parameter} />
				</AdvancedOptionsParameterRow>
			</Match>
			<Match when={props.parameter.domain.type == GameSetupDomainType.Boolean}>
				<AdvancedOptionsParameterRow rowName={stringCache.resolve(props.parameter.name)}>
					<AdvancedOptionBooleanField parameter={props.parameter} />
				</AdvancedOptionsParameterRow>
			</Match>
			<Match
				when={
					props.parameter.domain.type == GameSetupDomainType.Integer ||
					props.parameter.domain.type == GameSetupDomainType.UnsignedInteger ||
					props.parameter.domain.type == GameSetupDomainType.Text
				}
			>
				<AdvancedOptionsParameterRow rowName={stringCache.resolve(props.parameter.name)}>
					<AdvancedOptionTextField parameter={props.parameter} />
				</AdvancedOptionsParameterRow>
			</Match>
		</Switch>
	);
};

const AdvancedOptionsGameSetup: Component = () => {
	const model = GameSetupParameterGroupsModel.get();

	function isCategoryRedundant(setupParam: GameSetupParameter) {
		const categoryParamMap: Map<string, GameSetupDomainValue[]> = new Map<string, GameSetupDomainValue[]>();
		if (setupParam) {
			for (const pv of setupParam.domain.possibleValues ?? []) {
				const additionalPropsValue = pv.additionalProperties?.find(
					(ap) => ap.name == GameSetup.makeString("Category"),
				)?.value;
				let category = typeof additionalPropsValue === "string" ? additionalPropsValue : null;
				if (category == null) {
					const q = Database.query(
						"config",
						"SELECT Name from ParameterGroups where GroupID = ? LIMIT 1",
						GameSetup.resolveString(setupParam.group),
					);
					if (q && q.length > 0 && typeof q[0].Name == "string") {
						category = q[0].Name;
					}
				}

				if (category == null) {
					category = "LOC_ADVANCED_OPTIONS";
				}

				if (!categoryParamMap.get(category)) {
					categoryParamMap.set(category, [pv]);
				} else {
					categoryParamMap.get(category)!.push(pv);
				}
			}
		}
		const groupNameQuery = Database.query(
			"config",
			"SELECT Name from ParameterGroups where GroupID = ? LIMIT 1",
			GameSetup.resolveString(setupParam.group),
		);

		let groupName = null;
		if (groupNameQuery && groupNameQuery.length > 0 && typeof groupNameQuery[0].Name == "string") {
			groupName = groupNameQuery[0].Name;
		}

		const isSingleCategory = categoryParamMap.size == 1;
		const onlyCategoryKey = isSingleCategory ? [...categoryParamMap.keys()][0] : null;

		let categoryIsRedundant = false;
		if (
			isSingleCategory &&
			(onlyCategoryKey == GameSetup.resolveString(setupParam.name) || onlyCategoryKey == groupName)
		) {
			categoryIsRedundant = true;
		}

		return categoryIsRedundant;
	}

	return (
		<ScrollArea class="flex-auto">
			<SpatialSlot
				name="advanced-options-game-setup-slot"
				class="flex flex-col"
			>
				<For each={Object.entries(model.groups)}>
					{([groupId, parameters]) => {
						const parameterList = Object.values(parameters).filter(
							(param) =>
								typeof param == "object" &&
								!param.hidden &&
								!param.destroyed &&
								(param.domain.type != GameSetupDomainType.Select ||
									(param.domain.possibleValues?.length ?? 0) > 0) &&
								param.invalidReason == GameSetupParameterInvalidReason.Valid,
						);

						return parameterList.length > 0 ? (
							<div class="flex flex-col">
								<AdvancedOptionsAccordian title={model.groupNames.get(groupId) ?? groupId}>
									<AlternatingRows each={parameterList}>
										{(parameter) => (
											<AdvancedOptionField
												parameter={parameter}
												showHeader={!isCategoryRedundant(parameter)}
											/>
										)}
									</AlternatingRows>
								</AdvancedOptionsAccordian>
							</div>
						) : undefined;
					}}
				</For>
			</SpatialSlot>
		</ScrollArea>
	);
};

const AdvancedOptionsScreenComponent: Component = () => {
	const parametersModel = SetupParametersModel.get();
	const popupContext = usePopupContext();

	// Most likely single player but handle edge case.
	const gameConfig = Configuration.getGame();
	let saveType = SaveTypes.SINGLE_PLAYER;
	if (gameConfig.isHotseat) {
		saveType = SaveTypes.HOTSEAT;
	} else if (gameConfig.isInternetMultiplayer) {
		saveType = SaveTypes.NETWORK_MULTIPLAYER;
	}

	function showSaveScreen() {
		ContextManager.push("screen-save-load", {
			singleton: true,
			createMouseGuard: true,
			attributes: {
				"menu-type": "save_config",
				"server-type": ServerType.SERVER_TYPE_NONE,
				"save-type": saveType,
			},
		});
	}

	function showLoadScreen() {
		ContextManager.push("screen-save-load", {
			singleton: true,
			createMouseGuard: true,
			attributes: {
				"menu-type": "load_config",
				"server-type": ServerType.SERVER_TYPE_NONE,
				"save-type": saveType,
			},
		});
	}

	return (
		<div class="fullscreen flex flex-col">
			<Hotkeys hotkeys={[{ hotkeyAction: "cancel", onActivate: () => popupContext.close("advanced-options") }]} />

			<Frame.F1
				contentClass="px-22 pointer-events-auto"
				style={isMobile() ? {} : { "max-width": Layout.pixels(1280) }}
				safezoneMode={isMobile() ? SafezoneMode.Full : SafezoneMode.None}
			>
				<Header class="mb-4 text-center">
					<L10n.Compose text="LOC_ADVANCED_OPTIONS_ADVANCED" />
				</Header>
				<AudioContextProvider segment="AdvancedOptions">
					<Tab
						class="flex-auto flex flex-col"
						defaultTab="advanced-options-general"
					>
						<Tab.TabList class="w-full my-2" />
						<Tab.Output />
						<Tab.Item
							name="advanced-options-general"
							title={() => "LOC_ADVANCED_OPTIONS_GAME_SETTINGS"}
							body={() => <AdvancedOptionsGameSetup />}
						/>
						{/* TODO: REPLACE WITH VICTORIES <Tab.Item
						name="advanced-legacy-paths"
						title={() => "LOC_ADVANCED_OPTIONS_LEGACY_PATH_SETTINGS"}
						body={() => null}
						disabled={true}
						/> */}
						<Tab.Item
							name="advanced-options-player"
							title={() => <L10n.Compose text="LOC_ADVANCED_OPTIONS_PLAYER_SETTINGS" />}
							body={() => <AdvancedOptionsPlayerSetup />}
						/>
					</Tab>
				</AudioContextProvider>
				<div class="flex flex-row w-full pr-8 mt-2 items-end justify-between relative">
					<div class="flex flex-row">
						<Button
							class="uppercase mr-2 relative"
							disableFocus={true}
							hotkeyAction={"shell-action-3"}
							onActivate={parametersModel.resetToDefaults}
						>
							<L10n.Compose text="LOC_OPTIONS_RESET_TO_DEFAULTS" />
							<NavHelp class="ml-2" />
						</Button>
						<Tooltip.Text text={Locale.stylize("LOC_SAVE_LOAD_TITLE_SAVE_CONFIG")}>
							<Activatable
								class="advanced-options-save-button mx-2 size-12 bg-no-repeat bg-contain relative"
								disableFocus={true}
								hotkeyAction={"nav-shell-previous"}
								onActivate={showSaveScreen}
							>
								<NavHelp class="absolute -bottom-6 left-2" />
							</Activatable>
						</Tooltip.Text>
						<Tooltip.Text text={Locale.stylize("LOC_SAVE_LOAD_TITLE_LOAD_CONFIG")}>
							<Activatable
								class="advanced-options-load-button mx-2 size-12 bg-no-repeat bg-contain relative"
								disableFocus={true}
								hotkeyAction={"nav-shell-next"}
								onActivate={showLoadScreen}
							>
								<NavHelp class="absolute -bottom-6 left-2" />
							</Activatable>
						</Tooltip.Text>
					</div>
					<div class="flex flex-row items-center relative -right-8">
						<div class="filigree-h4-left mt-3" />
						<HeroButton2
							class="px-4 py-4 relative"
							disableFocus={true}
							hotkeyAction={"shell-action-1"}
							onActivate={() => popupContext.close("advanced-options")}
						>
							<L10n.Compose text="LOC_GENERIC_CONFIRM" />
							<NavHelp class="ml-2" />
						</HeroButton2>
						<div class="filigree-h4-right mt-3" />
					</div>
				</div>
			</Frame.F1>
		</div>
	);
};

export const AdvancedOptionsScreen = ComponentRegistry.register({
	name: "AdvancedOptionsScreen",
	createInstance: AdvancedOptionsScreenComponent,
	styles: [style],
});
